-- 仅只读；排除本批原服务精确6条新增身份后，比较全部52429旧行完整字段摘要。
SELECT c.relname table_name,(xpath('/row/row_count/text()',x.doc))[1]::text row_count,(xpath('/row/data_md5/text()',x.doc))[1]::text data_md5 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL (SELECT query_to_xml(format('SELECT count(*) AS row_count, md5(coalesce(string_agg(to_jsonb(t)::text, chr(10) ORDER BY to_jsonb(t)::text), '''')) AS data_md5 FROM public.%I t%s',c.relname,CASE c.relname WHEN 'business_operation_log' THEN ' WHERE NOT (uid IN (''e37659f7-5369-4b1c-a2c5-4a350339e701''))' WHEN 'command_receipt' THEN ' WHERE NOT (uid IN (''7d0a35bb-20d9-410a-b979-4a350339e70f''))' WHEN 'document_sequence' THEN ' WHERE NOT (uid IN (''31cc5d27-e6ae-4946-9d96-4a350339e6e8''))' WHEN 'purchase_order_head' THEN ' WHERE NOT (uid IN (''dd5d1603-1dad-423d-a0b4-4a350339e6bb''))' WHEN 'purchase_order_line' THEN ' WHERE NOT (uid IN (''20ce9b91-5826-48be-86cf-4a350339e6d5'',''d30d2d1d-1818-4e01-a913-4a350339e6dd''))' ELSE '' END),false,true,'') doc) x WHERE n.nspname='public' AND c.relkind='r' ORDER BY c.relname
